ProjectALife.DialogueShards["scenes_shelter_3"] = {
{"fw_ld6_shelter_civ_2_0073","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"Remember the ball game on the radio, the whole street had it on",2,"You could walk down the block and not miss a pitch",1,"Every window open, every radio on",3,"I'd listen to a bad game right now"}},
{"fw_ld6_shelter_civ_2_0074","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Don't point it at me",2,"It's not loaded",1,"That's what everybody says",2,"It's not loaded and I'm cleaning it",3,"Cleaning it where it's pointed at the room, that's a start"}},
{"fw_ld6_shelter_civ_2_0075","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Hold still",2,"I am holding still",1,"You're flinching",2,"It's a needle, it's going in my thumb",1,"Button, not thumb, hold the button"}},
{"fw_ld6_shelter_civ_2_0076","shelter",3,"reg=civilian,worker|mood=funny",{1,"I got duct tape on both boots",2,"What's holding the duct tape on",1,"Hope, and more duct tape",3,"That's about all anybody's got"}},
{"fw_ld6_shelter_civ_2_0077","shelter",3,"reg=civilian,family,worker,rescue",{1,"Water's boiling",2,"How long",1,"Ten minutes, then let it sit",2,"Ten minutes is a long time to look at a pot",3,"Don't look at it, it never boils"}},
{"fw_ld6_shelter_civ_2_0078","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Washing socks in a bucket, I've never been this happy",2,"You're smiling",1,"I found a bar of soap, a whole bar, it's almost lavender",2,"I'm so happy for you",3,"Is there enough for two socks"}},
{"fw_ld6_shelter_civ_2_0079","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Blister the size of a quarter",2,"Don't pop it",1,"It's already popped",2,"Then you're gonna want a bandage and a better attitude",3,"And a different pair of boots"}},
{"fw_ld6_shelter_civ_2_0080","shelter",4,"reg=civilian,family,worker,rescue",{1,"Splinter, left hand, it's deep",2,"Come here, let me see",1,"Be gentle",2,"I'm always gentle",1,"You are not",3,"Look away, it's easier"}},
{"fw_ld6_shelter_civ_2_0081","shelter",3,"reg=civilian,family,worker,rescue|mood=funny|world=window",{1,"The back of my neck's on fire",2,"You've got a sunburn",1,"From what, I haven't been outside in two days",2,"From the window, that's the window you sit by",3,"Move your chair"}},
{"fw_ld6_shelter_civ_2_0082","shelter",3,"reg=civilian,family,worker,rescue",{1,"I miss being able to ask if anybody had an Advil",2,"And somebody always did",1,"Funny what you took for granted",2,"A little bottle in somebody's purse",1,"Usually a good friend",2,"Who'd remind you not to take more than the label said",3,"I'd settle for hearing that lecture again"}},
{"fw_ld6_shelter_civ_2_0083","shelter",4,"reg=civilian,family,worker,rescue|mood=fear",{1,"My stomach's on fire, I think it's the water",2,"Did you boil it",1,"I boiled it",2,"How long",1,"...a while",3,"Boil it longer"}},
{"fw_ld6_shelter_civ_2_0084","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"You check me, I'll check you",2,"Sleeves up?",1,"And your neck, and behind your knees",2,"This is the worst game",1,"It's not a game, humor me",3,"Do it every morning, everybody"}},
{"fw_ld6_shelter_civ_2_0085","shelter",3,"reg=civilian,family,worker,rescue",{1,"My tooth's killing me",2,"Which one",1,"The back one, the one I wasn't gonna fix till the fall",2,"Whiskey?",1,"We don't have whiskey",3,"We might have a little whiskey"}},
{"fw_ld6_shelter_civ_2_0086","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Once dried my underwear on a picture frame",2,"Please tell me it wasn't a family portrait",1,"Only thing at the right height. Didn't think about it till afterward",3,"Bet the family looked pleased"}},
{"fw_ld6_shelter_civ_2_0087","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"Lord, we thank you for this food and for the can opener",2,"Amen",1,"And for Doyle not eating the whole can",3,"Amen, and I'm sorry"}},
{"fw_ld6_shelter_civ_2_0088","shelter",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"Nobody's asking you to pray, just be quiet while I do",2,"I'm quiet",1,"You're breathing at me",2,"I'm breathing at everybody"}},
{"fw_ld6_shelter_civ_2_0089","shelter",4,"reg=civilian,family,worker,rescue|hour=7,18|mood=funny",{1,"I haven't been to church since Easter",2,"Nobody has",1,"Easter, I wore a yellow dress, I felt like a lemon",2,"Pastor said you were a ray of sunshine",1,"Pastor lied",3,"Pastor lied about a lot of things, that's why it was a good sermon"}},
{"fw_ld6_shelter_civ_2_0090","shelter",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"God's gonna have some explaining to do",2,"Don't",1,"I'm not afraid of Him",2,"I know, that's what scares me"}},
{"fw_ld6_shelter_civ_2_0091","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"Do you know that hymn about the river?",2,"The one at funerals?",1,"The one at everything, I only know the first line",2,"Hum the first line, I'll try the second",3,"I know the third"}},
{"fw_ld6_shelter_civ_2_0092","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"I prayed for rain",2,"It's a hundred degrees",1,"I prayed for a little rain, a drizzle",2,"God doesn't do drizzle",3,"He did it in '87"}},
{"fw_ld6_shelter_civ_2_0093","shelter",4,"reg=civilian,family,worker,rescue|mood=sad",{1,"I prayed for my mother and then I prayed for my mother's dog",2,"That's a good prayer",1,"I felt bad about the dog, he was an idiot",2,"He's still a dog",3,"He's still a good dog"}},
{"fw_ld6_shelter_civ_2_0094","shelter",3,"reg=civilian,family,worker,rescue|mood=calm",{1,"Dog's whining out there",2,"Whose dog",1,"I don't know, it's just whining, it's been at it an hour",2,"Maybe he's lost",1,"Maybe he's hungry",3,"We're all hungry"}},
{"fw_ld6_shelter_civ_2_0095","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"If we had a dog I'd name him Biscuit",2,"Why Biscuit",1,"Because I could use a biscuit",3,"That's a good dog name"}},
{"fw_ld6_shelter_civ_2_0096","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"I used to read cereal boxes while everybody else read the paper",2,"What were you looking for?",1,"The maze. Same one every morning, and I'd still do it",2,"That was for kids",1,"I was half asleep. It was about my level",3,"I'd take a maze over the news now"}},
{"fw_ld6_shelter_civ_2_0097","shelter",3,"reg=civilian,family,worker,rescue|day=2,12|mood=sad",{1,"TV Guide from last week, what was on that Friday",2,"I don't wanna know",1,"A movie about a dog that saves a kid",2,"I'm gonna cry",3,"Don't, I'll cry too..."}},
{"fw_ld6_shelter_civ_2_0098","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"That's my girl, she's six",2,"She's got your chin",1,"She's got her mother's everything else",2,"Looks happy",1,"She was happy, that was a good day",3,"Look at those teeth"}},
{"fw_ld6_shelter_civ_2_0099","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"What was the last thing you ate before all this",2,"A Whopper Jr",1,"A junior?",2,"I was watching my weight",3,"Smart"}},
{"fw_ld6_shelter_civ_2_0100","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"I wrote my name in the dust on the table",2,"Why",1,"I don't know, to see it",2,"Rub it out, somebody'll see",1,"Somebody should..."}},
{"fw_ld6_shelter_civ_2_0101","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"If there's an afterlife I hope they've got air conditioning",2,"That's a bold assumption",1,"You think they don't",2,"I think it depends which one you get",3,"I'd take the one with ice"}},
{"fw_ld6_shelter_civ_2_0102","shelter",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"Nobody told me what to do, nobody came, I keep waiting for somebody in a uniform to show up and say go home",2,"Nobody's coming",1,"I know that, I KNOW that, I'm just tired of waiting for it to be true!"}},
{"fw_ld6_shelter_civ_2_0103","shelter",3,"reg=civilian,family,worker,rescue|day=7,10|mood=sad",{1,"I haven't cried yet and I'm waiting for it, like a sneeze",2,"It'll come",1,"It's been nine days, it'll come at a stupid time",3,"It'll be over a can opener or something"}},
{"fw_ld6_shelter_civ_2_0104","shelter",3,"reg=civilian,worker|mood=angry",{1,"If I hear one more person say we'll be fine I'm gonna fucking scream",2,"We'll be fine",1,"I'm gonna scream, I mean it",3,"Scream into a pillow, then, there's one right there"}},
{"fw_ld6_shelter_civ_2_0105","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"I'd trade everything I own for one hour of air conditioning and a Pepsi",2,"You own nothing",1,"I own the hour, I'm very motivated"}},
{"fw_ld6_shelter_civ_2_0106","shelter",3,"reg=family|mood=warm",{1,"They're finally asleep",2,"Both of them?",1,"Both, I told the one about the three bears twice",3,"Keep it down, don't jinx it"}},
{"fw_ld6_shelter_civ_2_0107","shelter",2,"reg=family|mood=funny",{1,"Mom, can you not hug me in front of people",2,"There's nobody here",1,"Mamaw's here",2,"Mamaw's asleep, and she'd hug you too"}},
{"fw_ld6_shelter_civ_2_0108","shelter",3,"reg=family|mood=funny|world=door",{1,"What?",2,"I said the door's open",1,"What door?",2,"The DOOR!",3,"Can't hear a thing, just shout it"}},
{"fw_ld6_shelter_civ_2_0109","shelter",3,"reg=family|mood=sad",{1,"In '37 the river came up to Main Street, my daddy rowed a boat down Fourth",2,"You told me",1,"I'm telling you again, he rowed past the drugstore, past the movie house",2,"Tell it, I like it",3,"I like it too, every time"}},
{"fw_ld6_shelter_civ_2_0110","shelter",2,"reg=family|mood=sad",{1,"Mamaw's pills, we've got four days left",2,"Four?",1,"Four if she takes half",2,"Then she takes half, and we don't tell her"}},
{"fw_ld6_shelter_civ_2_0111","shelter",3,"reg=family|mood=funny",{1,"Dad joke, hi hungry, I'm Dad",2,"Don't",1,"Hi thirsty, I'm Dad",3,"Stop, you're on a roll"}},
{"fw_ld6_shelter_civ_2_0112","shelter",3,"reg=family|day=6,10|mood=funny",{1,"I miss MTV!",2,"You miss MTV!",1,"I miss the videos, I miss the guy with the hair",2,"You've been here a week",3,"It's been a long week for MTV!"}},
{"fw_ld6_shelter_civ_2_0113","shelter",3,"reg=family|mood=warm",{1,"Wear your shoes",2,"It's a hundred degrees",1,"You'll step on something",2,"I'm twenty-six",3,"Grown folks wear shoes, ask your mama"}},
{"fw_ld6_shelter_civ_2_0114","shelter",3,"reg=family|mood=funny",{1,"You took my turn",2,"I did not",1,"I was next, you cut",2,"You're not the boss because you're older",3,"I'm the boss because I'm louder"}},
{"fw_ld6_shelter_civ_2_0115","shelter",2,"reg=family|mood=sad",{1,"Daddy's chair is empty, nobody sits in it",2,"It's a chair",1,"It's HIS chair, it's got the shape of him in it!",2,"...okay, nobody sits in it"}},
{"fw_ld6_shelter_civ_2_0116","shelter",3,"reg=family|mood=warm",{1,"I used to dread Sunday dinner, forty relatives and a ham",2,"Now?",1,"Now I'd give a kidney for the ham",3,"Take mine, I've got two"}},
{"fw_ld6_shelter_civ_2_0117","shelter",3,"reg=family|mood=funny",{1,"I'm bored",2,"Read a book",1,"There's no books",2,"Read a cereal box",1,"I did, it's got a maze",3,"Do the maze"}},
{"fw_ld6_shelter_civ_2_0118","shelter",3,"reg=family|mood=sad",{1,"Grandpa's pocketknife, he carried it every day for sixty years",2,"And now it's yours",1,"It's got his thumb in the handle, there's a groove",3,"Don't lose it..."}},
{"fw_ld6_shelter_civ_2_0119","shelter",2,"reg=family|mood=warm|world=hot",{1,"This quilt's the warmest thing I own",2,"It's too hot for a quilt",1,"It's for the smell, the heat's got nothing to do with it",2,"What does it smell like",1,"Home"}},
{"fw_ld6_shelter_civ_2_0120","shelter",3,"reg=family|mood=funny",{1,"Who's got the baby",2,"I thought you did",1,"I gave her to you",2,"You gave her to Mama",3,"Mama has her, Mama's had her for an hour, relax"}},
{"fw_ld6_shelter_civ_2_0121","shelter",3,"reg=family|mood=sad",{1,"I turned seventy-nine last month",2,"Happy birthday",1,"I was gonna have a cake, a little one, with one candle",2,"Next year",1,"Next year, sure"}},
{"fw_ld6_shelter_civ_2_0122","shelter",3,"reg=family|mood=funny",{1,"Somebody likes somebody here",2,"Who",1,"I'm not saying, I'm just saying somebody keeps looking",3,"It's the cat, you idiot"}},
{"fw_ld6_shelter_civ_2_0123","shelter",3,"reg=family|mood=funny",{1,"Chores",2,"There's no chores",1,"There's always chores, somebody's gotta do the dishes",2,"What dishes",3,"The can lids, stack them in the corner"}},
{"fw_ld6_shelter_civ_2_0124","shelter",3,"reg=family|mood=warm",{1,"Tell the one about when you were little",2,"Which one",1,"The one with the chicken",2,"I was five, there was a chicken in the kitchen, it had gotten in",3,"And it was Mama's good chicken, the one she was saving for Easter"}},
{"fw_ld6_shelter_civ_2_0125","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"Wednesday night service, I'd give anything",2,"The potluck?",1,"The singing, honestly, and then the potluck",3,"And the pastor's wife in the green dress"}},
{"fw_ld6_shelter_civ_2_0126","shelter",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"I pray for everybody by name, every night, it takes forty minutes",2,"That's a lot of names",1,"I get up to Delbert, fall asleep, start over"}},
{"fw_ld6_shelter_civ_2_0127","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Brother Dale used to say the Lord works in mysterious ways",2,"And?",1,"And I'd like to know what the Lord is working on, because it's a mess",3,"Amen"}},
{"fw_ld6_shelter_civ_2_0128","shelter",4,"reg=civilian,family,worker,rescue|mood=warm",{1,"Somebody start a hymn",2,"I don't know any",1,"You know one, you know the one about the bridge",2,"Bridge over what",3,"I'll start it, you'll know it"}},
{"fw_ld6_shelter_civ_2_0129","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"Preacher's wife used to bring a casserole to every funeral",2,"I remember",1,"There'd be six casseroles and nobody ate them",3,"Everybody ate them..."}},
{"fw_ld6_shelter_civ_2_0130","shelter",3,"reg=worker|day=1,13|mood=funny",{1,"I was on overtime at the plant when it started",2,"Time and a half?",1,"Double, it was Friday",3,"You'll never see it"}},
{"fw_ld6_shelter_civ_2_0131","shelter",2,"reg=worker|mood=funny",{1,"Foreman said finish the shift",2,"Finish the shift?",1,"Finish the shift, I did, I clocked out and everything",2,"Of course you did"}},
{"fw_ld6_shelter_civ_2_0132","shelter",3,"reg=worker|day=1,13|mood=sad",{1,"Payday's Friday",2,"It was Friday",1,"I know, I mean next Friday, I keep thinking I'm gonna get paid",3,"Check's in the mail"}},
{"fw_ld6_shelter_civ_2_0133","shelter",2,"reg=worker|mood=funny",{1,"I fixed a radiator with duct tape and spite once",2,"Did it hold",1,"Eleven miles, it held eleven miles",2,"That's all spite's good for"}},
{"fw_ld6_shelter_civ_2_0134","shelter",3,"reg=worker|mood=angry",{1,"Union said we'd have protection",2,"From what",1,"From the company, I don't know, from anything",3,"Union's got a lot of explaining to do"}},
{"fw_ld6_shelter_civ_2_0135","shelter",3,"reg=worker|mood=funny",{1,"My hands haven't been this clean in thirty years",2,"Because you're not working",1,"I miss the grease, I feel naked",3,"You are naked, you have no gloves"}},
{"fw_ld6_shelter_civ_2_0136","shelter",2,"reg=worker|day=1,6|mood=sad|world=door",{1,"I was supposed to be on the line at six Monday",2,"You still gonna go?",1,"I'm gonna sit by the door at five-thirty, just in case"}},
{"fw_ld6_shelter_civ_2_0137","shelter",3,"reg=rescue|mood=sad",{1,"I'm out of gauze",2,"There's some in the second bag",1,"That's the last of it, I've been rationing it",3,"I'll find more, there's got to be a pharmacy"}},
{"fw_ld6_shelter_civ_2_0138","shelter",2,"reg=rescue|role=rescue_firefighter|mood=grim",{1,"I keep smelling smoke",2,"There's no smoke",1,"I know there's no smoke, I smell it every night, since the station",2,"I know"}},
{"fw_ld6_shelter_civ_2_0139","shelter",3,"reg=rescue|day=2,6|mood=warm",{1,"I'm out of sermons",2,"You've been preaching for three days",1,"I've said everything I know, and some things I don't",3,"Just sit with us, that's a sermon"}},
{"fw_ld6_shelter_civ_2_0140","shelter",2,"reg=rescue|role=rescue_clergy|mood=sad",{1,"Pray with me",2,"I don't know what to say",1,"Just say hello, and then say help",2,"Hello, help"}},
{"fw_ld6_shelter_civ_2_0141","shelter",3,"reg=rescue|mood=funny",{1,"I never thought I'd miss a house fire",2,"Why",1,"At least there was a plan, a hose, a ladder, a way to do it",3,"This is a fire without a hose"}},
{"fw_ld6_shelter_civ_2_0142","shelter",3,"reg=rescue|mood=sad",{1,"I used to hold their hands, in the ambulance",2,"I know",1,"And I don't know where to put my hands now",3,"Put 'em here, hold mine, it's all right"}},
{"fw_ld6_shelter_civ_2_0143","shelter",4,"reg=civilian,family,worker,rescue|world=door",{1,"How do you decide who to let stay?",2,"I talk to them. That's about all I've got",1,"People can tell you anything",2,"I know. I pay more attention to what they do afterward",3,"And I still keep my things close. Both can be true"}},
{"fw_ld6_shelter_civ_2_0144","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"Don't let anybody know I'm this scared",2,"We're scared too. Nobody needs to hear it from me",1,"I mean, don't tell them I said it. Please",3,"Said what?"}},
{"fw_ld6_shelter_civ_2_0145","shelter",3,"reg=civilian,family,worker,rescue|mood=angry",{1,"Where's Lonnie?",2,"Out",1,"Out where",2,"I don't know, he said he needed air",3,"Air's a lot of places"}},
{"fw_ld6_shelter_civ_2_0146","shelter",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"Somebody's been taking from the food, and I'm not saying who, but it's somebody with a belly",2,"Don't",1,"I'm just saying it's the one with the belly",2,"Everybody's got a belly right now"}},
{"fw_ld6_shelter_civ_2_0147","shelter",3,"reg=civilian,family,worker,rescue",{1,"I heard the Army's got a camp up in Louisville",2,"From who",1,"A guy on the road, he said they've got tents and hot meals",2,"A guy on the road",3,"I'd walk there for a hot meal"}},
{"fw_ld6_shelter_civ_2_0148","shelter",3,"reg=civilian,family,worker,rescue|day=2,14|mood=fear",{1,"Somebody said it started at the chemical plant",2,"Somebody says a lot",1,"They said there was a leak and by Friday people were sick",3,"It started everywhere at once, that's what I heard"}},
{"fw_ld6_shelter_civ_2_0149","shelter",3,"reg=civilian,family,worker,rescue",{1,"Somebody said the President's in a bunker",2,"Which one",1,"I don't know, the one under whatever's under Washington",3,"That's a lot of bunkers"}},
{"fw_ld6_shelter_civ_2_0150","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"You know what, I'm glad you're all here",2,"Don't get sappy",1,"I'm not getting sappy, I'm just saying it in a flat voice",3,"That's the worst kind of sappy"}},
{"fw_ld6_shelter_civ_3_0001","shelter",3,"reg=law,swat,civilian,family,worker,rescue|r1=law,swat|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|mood=warm",{1,"Y'all eat anything today?",2,"Half a can of beans",3,"I had a cracker",1,"Here, I've got a Snickers in my vest, split it three ways"}},
{"fw_ld6_shelter_civ_3_0002","shelter",3,"reg=law,swat,civilian,family,worker,rescue|r1=law,swat|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|mood=calm|world=door",{1,"Don't sit with your back to the door",2,"Why?",1,"Habit, you want to see who comes in",3,"Who comes in?",1,"Nobody, that's the habit"}},
{"fw_ld6_shelter_civ_3_0003","shelter",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|mood=sad",{1,"Officer, do you think they're still looking for us?",2,"Somebody's looking, I just don't know who",1,"That's not very reassuring",2,"Wasn't trying to reassure you, I just don't have anything better"}},
{"fw_ld6_shelter_civ_3_0004","shelter",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|hour=16,5|mood=funny",{1,"Is it true you can write a ticket for anything?",2,"Anything with a reason",3,"Busy drinking warm water, no tickets tonight",1,"Write one for the heat",3,"Fine, ten bucks"}},
{"fw_ld6_shelter_civ_3_0005","shelter",3,"reg=law,swat,civilian,family,worker,rescue|r1=law,swat|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|mood=calm",{1,"Which one of you knows how to drive a stick?",2,"Me",3,"Me too",1,"Good, we may need that, I'll show you the road"}},
{"fw_ld6_shelter_civ_3_0006","shelter",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=1,13|mood=warm",{1,"Can I ask something dumb?",2,"Go ahead",1,"Were you scared Friday?",2,"Yeah, I was, I still am, I'm just better at not showing it"}},
{"fw_ld6_shelter_civ_3_0007","shelter",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|mood=fear|world=building",{1,"I thought I heard something upstairs",2,"It's the house",3,"I'll check it, stay here",1,"Be careful",3,"Always"}},
{"fw_ld6_shelter_civ_3_0008","shelter",3,"reg=military,elite,civilian,family,worker,rescue|r1=military,elite|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|mood=calm",{1,"What do you say when somebody asks for water and you can't spare any?",2,"The truth, I hope",3,"Even when they only want a swallow?",1,"Especially then. Don't make them wait on water you haven't got"}},
