{"fw_ld6_shelter_civ_3_0012","shelter",2,"reg=rescue,civilian,family,worker|r1=rescue|r2=civilian,family,worker,rescue|mood=calm",{1,"Let me see that arm",2,"It's fine",1,"Let me see it anyway...",2,"...it's a little red",1,"It's more than a little red, we'll clean it again"}},
{"fw_ld6_shelter_civ_3_0013","shelter",3,"reg=rescue,civilian,family,worker|r1=rescue|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|mood=funny",{1,"Nobody sleeps in their boots, take them off, air out your feet",2,"What if we have to go",1,"Then you'll run in socks",3,"That's worse",1,"That's why you have boots, now take them off"}},
{"fw_ld6_shelter_civ_3_0014","shelter",3,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=rescue|mood=warm",{1,"We got a little bit of sugar",2,"Let's save it",3,"I'll make tea, I've got a little pot",1,"We don't have tea",3,"I have tea"}},
{"fw_ld6_shelter_civ_3_0015","shelter",3,"reg=civilian,worker|mood=angry|world=inside",{1,"It's so damn hot in here I can't think straight, my brain's like warm soup",2,"Then don't think",1,"I haven't had a decent night's sleep since the sixth, I'm gonna kill the next person who breathes!",3,"That's me, I'm breathing, go ahead"}},
{"fw_ld6_shelter_civ_3_0016","shelter",2,"reg=civilian,worker|mood=angry",{1,"My ass has been numb for two days from this goddamn floor",2,"Sit on something",1,"There's nothing to sit on, I've tried the table, the table's worse",2,"Then stand, stop telling me about your ass"}},
{"fw_ld6_shelter_civ_3_0017","shelter",3,"reg=civilian,worker|day=3,7|mood=angry",{1,"If I hear that radio static one more fucking time!",2,"I'm listening for a voice",1,"There's no voice, it's static, it's been static for four days!",3,"Turn it down, don't turn it off, I like the hiss"}},
{"fw_ld6_shelter_civ_3_0018","shelter",2,"reg=civilian,family,worker,rescue|mood=fear",{1,"Every little noise and my heart's going like a drum, I can't make it stop",2,"Breathe",1,"I AM breathing, that's why I can hear it",2,"Come sit down, you're white as a sheet"}},
{"fw_ld6_shelter_civ_3_0019","shelter",2,"reg=civilian,family,worker,rescue|mood=fear",{1,"Go check the back, again, please",2,"I checked it ten minutes ago",1,"Check it again, please, I won't be able to sit if you don't",2,"...fine, but I'm not gonna enjoy it"}},
{"fw_ld6_shelter_civ_3_0020","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"What if they can hear us breathing",2,"They can't",1,"How do you know that? Nobody knows that!",3,"Hush, both of you, just hush"}},
{"fw_ld6_shelter_civ_3_0021","shelter",2,"reg=civilian,family,worker,rescue|mood=fear",{1,"I-- I can't do this, I can't, I'm not built for this",2,"Nobody's built for it",1,"You are, you're calm, how are you calm",2,"I'm not calm, I'm just not moving"}},
{"fw_ld6_shelter_civ_3_0022","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"I keep seeing Mrs. Hadley from next door, in her window",2,"Don't",1,"She was just standing there, in her nightgown, waving, like she wanted me to come over",3,"She wasn't waving at you"}},
{"fw_ld6_shelter_civ_3_0023","shelter",2,"reg=civilian,worker|day=5,10|mood=sad",{1,"I forgot my dad's birthday was Tuesday, I remembered just now, TUESDAY!",2,"It's okay",1,"It's not okay, I always called, even when he was a dick, I always called",2,"So call him in your head, he'll hear it"}},
{"fw_ld6_shelter_civ_3_0024","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"I keep saving the good coat for my mother",2,"She'd want you to wear it",1,"She's not here, and I'm saving it, it's stupid, it's a coat",3,"It's a good coat, wear it"}},
{"fw_ld6_shelter_civ_3_0025","shelter",3,"reg=civilian,worker|mood=angry",{1,"Where the fuck is the Army? I pay taxes! I paid for those tanks!",2,"They're coming",1,"Everybody keeps saying they're coming, it's been a goddamn week!",3,"Don't yell, you'll bring the neighborhood"}},
{"fw_ld6_shelter_civ_3_0026","shelter",3,"reg=civilian,family,worker,rescue|mood=angry",{1,"They told us stay inside, they told us stay calm, and then they cut the lines",2,"I know",1,"Some bureaucrat in Frankfort is eating a sandwich right now and he doesn't know my name",3,"He doesn't know any of our names"}},
{"fw_ld6_shelter_civ_3_0027","shelter",3,"reg=civilian,worker|day=2,2|mood=funny",{1,"At least I don't have to go to work Monday",2,"Monday's tomorrow",1,"Fuck",3,"Congratulations, you remembered"}},
{"fw_ld6_shelter_civ_3_0028","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"I always said this county would go to hell, I just thought it'd take longer",2,"It was a good county",1,"It had its moments, I'd say it had a decent Dairy Queen",3,"I'll drink to that, if we had anything to drink"}},
{"fw_ld6_shelter_civ_3_0029","shelter",2,"reg=civilian,worker|mood=funny",{1,"I'd trade my left arm for a bag of ice",2,"You need that arm",1,"I'd trade my right arm too, I'd learn to use my feet"}},
{"fw_ld6_shelter_civ_3_0030","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"I can smell my own feet from over here, and I'm sitting on them",2,"That's physically impossible",1,"Then tell my nose, it's very confused"}},
{"fw_ld6_shelter_civ_3_0031","shelter",3,"reg=civilian,worker|mood=angry",{1,"Somebody's chewing, I can hear them chewing, STOP!",2,"It's a cracker",1,"It's a loud goddamn cracker!",3,"Chew with your mouth closed, hon"}},
{"fw_ld6_shelter_civ_3_0032","shelter",2,"reg=civilian,worker|mood=angry|world=window",{1,"If you say 'we've got this' one more time I'll throw you through that window",2,"We've got this",1,"I'm warning you",2,"We've got this"}},
{"fw_ld6_shelter_civ_3_0033","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"I miss my bed, I miss my stupid lumpy bed, it had a dip in the middle exactly where my body went",2,"I miss my pillow",1,"I'd marry my pillow, I'd have its babies",2,"Calm down"}},
{"fw_ld6_shelter_civ_3_0034","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"What if nobody's coming",2,"Don't",1,"I'm just asking, what if it's just us",3,"Then it's just us, eat your beans"}},
{"fw_ld6_shelter_civ_3_0035","shelter",2,"reg=civilian,worker|mood=grim",{1,"Do you ever think about how many are out there?",2,"No",1,"Hundreds, thousands, all of them walking around, with nowhere to go",2,"Fuck's sake, I'm trying to eat"}},
{"fw_ld6_shelter_civ_3_0036","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"You know what I miss? Cutting the grass",2,"Nobody misses cutting the grass",1,"I do, I'd give a hundred bucks to push a mower around the yard for an hour",3,"Come push mine, I'll watch..."}},
{"fw_ld6_shelter_civ_3_0037","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"If I'd known this was the last week I'd have eaten the whole pie",2,"Which pie?",1,"The one in the fridge, the lemon meringue, I was being good, I was saving it",3,"Never save the pie"}},
{"fw_ld6_shelter_civ_3_0038","shelter",2,"reg=civilian,worker|mood=funny",{1,"I want a cheeseburger so bad I'd sleep with a Burger King, I don't care which one",2,"You're a disgusting human being",1,"I'm a hungry one"}},
{"fw_ld6_shelter_civ_3_0039","shelter",2,"reg=civilian,family,worker,rescue|day=2,13|mood=angry",{1,"I'm not gonna sit here and be told what to do by somebody I met on Saturday",2,"I'm trying to help",1,"You're trying to be in charge, there's a difference"}},
{"fw_ld6_shelter_civ_3_0040","shelter",3,"reg=civilian,family,worker,rescue|mood=angry|world=building",{1,"Whose idea was it to stay in this house anyway?",2,"Yours",1,"That wasn't mine, that was Pete's thing",3,"Pete's not here, so it was somebody's idea, shut up"}},
{"fw_ld6_shelter_civ_3_0041","shelter",2,"reg=civilian,worker|x1=f|mood=sad",{1,"My ex-husband's the one I think about, can you believe that? That asshole",2,"Which one?",1,"The first one, he had the worst temper, and he'd have known what to do",2,"He'd have shot at something and run"}},
{"fw_ld6_shelter_civ_3_0042","shelter",2,"reg=civilian,family,worker,rescue|x1=f|mood=fear",{1,"I had to tell the kids Daddy wasn't coming home, I had to say it in the kitchen",2,"I'm sorry",1,"I didn't know the words, I used the wrong words, I said gone",2,"Gone's all right, gone's what it is"}},
{"fw_ld6_shelter_civ_3_0043","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"Did you ever fix that thing with your brother?",2,"What thing",1,"The fight, at the funeral",2,"No",3,"Then do it, if he's out there"}},
