{"fw_ld6_shelter_civ_3_0045","shelter",2,"reg=civilian,worker|hour=4,11|mood=angry",{1,"Take your goddamn boots off before you come in!",2,"It's a dirt floor!",1,"It's a dirt floor in MY house! I wiped it this morning!",2,"You wiped dirt"}},
{"fw_ld6_shelter_civ_3_0046","shelter",3,"reg=civilian,family,worker,rescue|mood=angry",{1,"I'm sick of being told to be quiet, I'm gonna scream",2,"Don't",1,"I'm-- I'm gonna scream into this jacket, give me a minute",3,"Scream into the bucket, it'll be more satisfying"}},
{"fw_ld6_shelter_civ_3_0047","shelter",3,"reg=civilian,worker|day=6,10|mood=funny",{1,"Good news, I found a hot dog in the freezer",2,"The freezer's off",1,"It's been off for a week, the hot dog's pretty confident",3,"That hot dog's got a face on it, put it back"}},
{"fw_ld6_shelter_civ_3_0048","shelter",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"I'm glad you're here, I didn't think I'd say it, but I'm glad",2,"You're gonna make me cry and I've got no water to spare",1,"I'll cry for both of us, I've got a canteen"}},
{"fw_ld6_shelter_civ_3_0049","shelter",3,"reg=civilian,worker|x1=m|mood=funny",{1,"I'd give my left nut for a cigarette",2,"That's a lot of nut",1,"It's a mid-sized nut",3,"Take it up with the guy who's got a pack"}},
{"fw_ld6_shelter_civ_3_0050","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"My hands won't stop shaking, look at them",2,"Hold them still",1,"I'm TRYING, they've got a mind of their own!",3,"Put them in your pockets"}},
{"fw_ld6_shelter_civ_3_0051","shelter",3,"reg=civilian,worker|mood=grim",{1,"You hear it? The moaning, way out, like cows",2,"It's not cows",1,"I know it's not cows, I'm trying to pretend it's cows",3,"Pretend harder..."}},
